;color:#a8bdd7;font-size:12px;font-weight:800;text-transform:uppercase;letter-spacing:.08em}.dot{width:7px;height:7px;border-radius:50%;background:var(--green);box-shadow:0 0 12px var(--green)}h1{font-size:clamp(46px,7vw,78px);line-height:1.02;letter-spacing:-.045em;margin:24px 0 20px}.gradient{background:linear-gradient(90deg,#fff,#75cfff 45%,#9878ff);-webkit-background-clip:text;color:transparent}.lead{font-size:clamp(17px,2vw,20px);color:#96a9c2;max-width:680px;margin:0 auto 32px}.hero-actions{display:flex;justify-content:center;gap:12px;flex-wrap:wrap}.trust{margin-top:35px;display:flex;justify-content:center;gap:26px;flex-wrap:wrap;color:#7186a2;font-size:13px}.trust b{color:#c7d5e7}.section{padding:84px 0}.section.alt{background:#07111f;border-top:1px solid #10233a;border-bottom:1px solid #10233a}.eyebrow{color:#6faeff;font-size:12px;font-weight:900;letter-spacing:.14em;text-transform:uppercase}.section h2{font-size:clamp(30px,4vw,46px);letter-spacing:-.03em;margin:8px 0 12px}.section-copy{color:var(--muted);max-width:640px}.features{display:grid;grid-template-columns:repeat(3,1fr);gap:16px;margin-top:34px}.feature,.product,.stat,.empty{background:linear-gradient(145deg,#0c192b,#091422);border:1px solid var(--line);border-radius:18px;padding:24px}.icon{width:42px;height:42px;border-radius:12px;display:grid;place-items:center;background:#132945;border:1px solid #23476d;font-size:20px}.feature h3{margin:17px 0 7px}.feature p{margin:0;color:var(--muted);font-size:14px}.products{display:grid;grid-template-columns:repeat(3,1fr);gap:18px;margin-top:35px}.product{position:relative;transition:.2s transform,.2s border-color}.product:hover{transform:translateY(-4px);border-color:#365a87}.product.featured{border-color:#6c55ff;box-shadow:0 0 0 1px #6c55ff,0 20px 55px #402bd625}.badge{display:inline-flex;padding:6px 9px;border-radius:7px;background:#102b46;color:#6fd7ff;font-size:11px;font-weight:900;text-transform:uppercase}.featured .badge{background:#392c78;color:#c7bbff}.product h3{font-size:22px;margin:15px 0 4px}.desc{color:var(--muted);font-size:14px;min-height:44px}.price{font-size:35px;font-weight:900;margin:20px 0}.price small{font-size:13px;color:var(--muted);font-weight:600}.specs{display:grid;grid-template-columns:1fr 1fr;gap:9px;padding:17px 0;border-top:1px solid var(--line);color:#b6c6d9;font-size:13px}.product .btn{width:100%;margin-top:8px}.stats{display:grid;grid-template-columns:repeat(4,1fr);gap:14px;margin-top:32px}.stat b{font-size:26px;display:block}.stat span{font-size:12px;color:var(--muted)}.cta{border:1px solid #294768;background:radial-gradient(500px 200px at 20% 0,#244d804d,transparent),#0a1727;border-radius:24px;padding:40px;display:flex;align-items:center;justify-content:space-between;gap:25px}.cta h2{margin:0 0 8px}.footer{padding:38px 0 50px;border-top:1px solid #13263d;color:#7186a0}.foot{display:flex;justify-content:space-between;gap:25px;align-items:center}.empty{text-align:center;grid-column:1/-1;padding:45px}.empty .icon{margin:auto}.empty h3{font-size:23px;margin-bottom:5px}.empty p{color:var(--muted);margin-top:0}
@media(max-width:850px){.links{display:none}.features,.products{grid-template-columns:1fr 1fr}.stats{grid-template-columns:1fr 1fr}.hero{padding:75px 0 65px}.cta{align-items:flex-start;flex-direction:column}}@media(max-width:560px){.container{width:min(100% - 24px,1180px)}.navin{height:64px}.brand span:last-child{font-size:16px}.actions .btn:first-child{display:none}.btn{padding:11px 13px}.hero{padding:65px 0 55px}h1{font-size:45px}.features,.products{grid-template-columns:1fr}.stats{grid-template-columns:1fr 1fr}.section{padding:60px 0}.cta{padding:27px}.foot{align-items:flex-start;flex-direction:column}.product .desc{min-height:0}}
