@empty<div class="empty"><div class="icon">☁</div><h3>Serverpakker er på vej</h3><p>Der er endnu ingen aktive produkter. Opret dem under Admin → Storefront & Billing.</p>@auth<a class="btn" href="/admin/store">Administrér produkter</a>@endauth</div>@endforelse
